result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "auditlog.py", "content": """"Hash-chained, rotating JSONL audit logger.

Each record is one JSON line:
    {"seq": <int>, "prev": <hex>, "event": {...}, "h": <hex>}

where h = sha256(f"{seq}|{sorted-json(event)}|{prev}").

Records are appended to segments ``audit-<k>.log``. When a segment holds
``max_records`` records it is closed and a new segment begins whose first
record's ``prev`` is the final hash of the previous segment. A
``manifest.json`` tracks the segment order and each segment's final hash.
"""

from __future__ import annotations

import hashlib
import json
import os
from typing import Any, Dict, List, Optional

GENESIS = "0" * 64


class AuditError(Exception):
    """Raised for writer misuse; also base class for verification issues."""


def _hash(seq: int, event: dict, prev: str) -> str:
    payload = f"{seq}|{json.dumps(event, sort_keys=True)}|{prev}"
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _record_json(rec: Dict[str, Any]) -> str:
    return json.dumps(rec, sort_keys=True)


def _read_segment(path: str) -> List[Dict[str, Any]]:
    recs = []
    with open(path, "r", encoding="utf-8") as f:
        for lineno, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                recs.append(json.loads(line))
            except json.JSONDecodeError as exc:
                raise ValueError(f"{os.path.basename(path)}:{lineno}: bad JSON: {exc}")
    return recs


class AuditWriter:
    def __init__(self, directory: str, max_records: int = 100):
        self.dir = os.fspath(directory)
        self.max_records = max_records
        if max_records <= 0:
            raise ValueError("max_records must be positive")
        os.makedirs(self.dir, exist_ok=True)

        self._manifest = self._load_or_init_manifest()
        self._seq = 0
        self._last_hash = GENESIS
        self._seg_index = len(self._manifest["segments"])
        self._seg_count = 0
        self._fh: Optional[Any] = None

        self._resume_state()
        self._open_segment()

    # -- setup helpers ----------------------------------------------------

    def _manifest_path(self) -> str:
        return os.path.join(self.dir, "manifest.json")

    def _segment_path(self, k: int) -> str:
        return os.path.join(self.dir, f"audit-{k}.log")

    def _empty_manifest(self) -> Dict[str, Any]:
        return {"segments": []}

    def _load_or_init_manifest(self) -> Dict[str, Any]:
        path = self._manifest_path()
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                m = json.load(f)
            if "segments" not in m:
                raise AuditError("manifest.json missing 'segments'")
            return m
        return self._empty_manifest()

    def _resume_state(self) -> None:
        """Recover seq/chain state from existing segments (if any)."""
        for entry in self._manifest["segments"]:
            path = self._segment_path(entry["index"])
            if not os.path.exists(path):
                continue
            recs = _read_segment(path)
            if not recs:
                continue
            self._seq = recs[-1]["seq"]
            self._last_hash = recs[-1]["h"]

        # A trailing segment may exist on disk beyond the manifest (crash
        # between rotation and manifest write); fold it into the manifest.
        while os.path.exists(self._segment_path(self._seg_index)):
            path = self._segment_path(self._seg_index)
            recs = _read_segment(path)
            final = recs[-1]["h"] if recs else self._last_hash
            self._manifest["segments"].append(
                {"index": self._seg_index, "name": f"audit-{self._seg_index}.log",
                 "records": len(recs), "final_hash": final}
            )
            if recs:
                self._seq = recs[-1]["seq"]
                self._last_hash = recs[-1]["h"]
                self._seg_count = len(recs)
            self._seg_index += 1
            if self._seg_count >= self.max_records:
                self._rotate_state_only()
        self.write_manifest()

    def _open_segment(self) -> None:
        self._fh = open(self._segment_path(self._seg_index), "a", encoding="utf-8")

    def _rotate_state_only(self) -> None:
        self._seg_count = 0
        self._seg_index += 1

    # -- public API --------------------------------------------------------

    def append(self, event: dict) -> Dict[str, Any]:
        if self._fh is None:
            raise AuditError("writer is closed")
        if self._seg_count >= self.max_records:
            self._close_current(update_manifest=True)
            self._rotate_state_only()
            self._open_segment()

        self._seq += 1
        rec = {
            "seq": self._seq,
            "prev": self._last_hash,
            "event": event,
            "h": _hash(self._seq, event, self._last_hash),
        }
        self._fh.write(_record_json(rec) + "\n")
        self._fh.flush()
        os.fsync(self._fh.fileno())
        self._last_hash = rec["h"]
        self._seg_count += 1
        return rec

    def _close_current(self, update_manifest: bool = True) -> None:
        if self._fh is None:
            return
        self._fh.close()
        self._fh = None
        k = self._seg_index
        segments = self._manifest["segments"]
        entry = {
            "index": k,
            "name": f"audit-{k}.log",
            "records": self._seg_count,
            "final_hash": self._last_hash,
        }
        if segments and segments[-1]["index"] == k:
            segments[-1] = entry
        else:
            segments.append(entry)
        if update_manifest:
            self.write_manifest()

    def write_manifest(self) -> None:
        tmp = self._manifest_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(self._manifest, f, indent=2)
        os.replace(tmp, self._manifest_path())

    def close(self) -> None:
        self._close_current(update_manifest=True)

    def __enter__(self) -> "AuditWriter":
        return self

    def __exit__(self, *exc: Any) -> None:
        self.close()

    @property
    def seq(self) -> int:
        return self._seq


# -- verification -----------------------------------------------------------


def verify_all(directory: str) -> List[str]:
    """Validate all segments, cross-segment linkage, and the manifest.

    Returns a list of human-readable problems; an empty list means the log
    is fully consistent. Each problem mentions the offending segment name
    and sequence number where applicable.
    """
    d = os.fspath(directory)
    errors: List[str] = []
    mpath = os.path.join(d, "manifest.json")
    if not os.path.exists(mpath):
        return ["manifest.json missing"]

    try:
        with open(mpath, "r", encoding="utf-8") as f:
            manifest = json.load(f)
    except json.JSONDecodeError as exc:
        return [f"manifest.json unreadable: {exc}"]

    segments = manifest.get("segments")
    if not isinstance(segments, list):
        return ["manifest.json has no 'segments' list"]

    # Segment files on disk vs manifest (detect deletions/extras).
    disk = sorted(
        n for n in os.listdir(d)
        if n.startswith("audit-") and n.endswith(".log")
    )
    listed = [e["name"] for e in segments]
    for name in listed:
        if name not in disk:
            errors.append(f"manifest lists segment {name} but the file is missing")
    for name in disk:
        if name not in listed:
            errors.append(f"segment {name} exists on disk but is not in the manifest")

    expected_seq = 1
    prev_hash = GENESIS

    for pos, entry in enumerate(segments):
        name = entry["name"]
        path = os.path.join(d, name)
        if not os.path.exists(path):
            continue
        try:
            recs = _read_segment(path)
        except ValueError as exc:
            errors.append(str(exc))
            break

        if recs:
            first_prev = recs[0].get("prev")
            if first_prev != prev_hash:
                errors.append(
                    f"{name}: first record seq={recs[0].get('seq')} prev "
                    f"does not match expected hash "
                    f"(expected {str(prev_hash)[:12]}..., got {str(first_prev)[:12]}...)"
                )

        for rec in recs:
            seq = rec.get("seq")
            if seq != expected_seq:
                errors.append(
                    f"{name}: seq={seq} out of order (expected {expected_seq})"
                )
            try:
                want = _hash(rec["seq"], rec["event"], rec["prev"])
            except (KeyError, TypeError):
                errors.append(f"{name}: seq={seq} record is malformed")
                expected_seq += 1
                continue
            if rec.get("h") != want:
                errors.append(
                    f"{name}: seq={seq} hash mismatch (record or event was tampered)"
                )
            expected_seq += 1

        final = recs[-1]["h"] if recs else prev_hash
        if entry.get("final_hash") != final:
            errors.append(
                f"{name}: manifest final_hash mismatch "
                f"(manifest {str(entry.get('final_hash'))[:12]}..., "
                f"actual {str(final)[:12]}...)"
            )
        prev_hash = final

    return errors


def assert_ok(directory: str) -> None:
    """Convenience wrapper: raise AuditError if verify_all finds problems."""
    problems = verify_all(directory)
    if problems:
        raise AuditError("; ".join(problems))
